using VitalTrek.API.IncidentResponse.Domain.Model.Aggregates;
using VitalTrek.API.Shared.Domain.Repositories;

namespace VitalTrek.API.IncidentResponse.Domain.Repositories;

/// <summary>
///     Domain repository interface for managing <see cref="EvacuationAction"/> aggregates.
/// </summary>
public interface IEvacuationActionRepository : IBaseRepository<EvacuationAction>
{
    /// <summary>Finds an action of an agency by the identity generated by the client.</summary>
    Task<EvacuationAction?> FindByClientActionIdAsync(int agencyId, Guid clientActionId,
        CancellationToken cancellationToken = default);

    /// <summary>Finds the actions of an incident of an agency ordered by capture time.</summary>
    Task<IEnumerable<EvacuationAction>> FindByIncidentIdAsync(int agencyId, int incidentId,
        CancellationToken cancellationToken = default);

    /// <summary>Counts the actions recorded for the given incidents of an agency.</summary>
    Task<int> CountByIncidentIdsAsync(int agencyId, IReadOnlyCollection<int> incidentIds,
        CancellationToken cancellationToken = default);
}
